import type {
  IsoTimestamp,
  OrgId,
  ProjectId,
  UserId,
} from "./common";
import type { IssuePriority } from "./issue";

export type RecurrenceCadence = "daily" | "weekly";

/**
 * A rule that a background job turns into ordinary issues. Dates are
 * `YYYY-MM-DD` strings in the rule's own `timezone`; `weekday` is the ISO
 * weekday (1 = Monday … 7 = Sunday) and is only set for weekly rules.
 */
export interface RecurringIssue {
  id: string;
  orgId: OrgId;
  projectId: ProjectId;
  title: string;
  priority: IssuePriority;
  assigneeId: UserId | null;
  cadence: RecurrenceCadence;
  weekday: number | null;
  timezone: string;
  startsOn: string;
  lastOccurrenceOn: string | null;
  paused: boolean;
  createdBy: UserId;
  createdAt: IsoTimestamp;
  updatedAt: IsoTimestamp;
}
EOF
cat > src/schemas/recurring-issue.ts <<'EOF'
import { z } from "zod";
import {
  orgIdSchema,
  projectIdSchema,
  userIdSchema,
} from "./common";
import { issuePrioritySchema } from "./issue";

const DATE_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;

/** True for a real calendar date written as `YYYY-MM-DD`. */
function isCalendarDate(value: string): boolean {
  const match = DATE_PATTERN.exec(value);
  if (match === null) return false;

  const [year, month, day] = [
    Number(match[1]),
    Number(match[2]),
    Number(match[3]),
  ];
  const date = new Date(0);
  date.setUTCFullYear(year, month - 1, day);

  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

/** True when the runtime's ICU data knows `value` as an IANA zone name. */
function isKnownTimeZone(value: string): boolean {
  // Newer runtimes also accept UTC offsets ("+01:00"), which are not IANA names.
  if (value === "" || /^[+-]/.test(value)) return false;
  try {
    new Intl.DateTimeFormat("en-US", { timeZone: value });
    return true;
  } catch {
    return false;
  }
}

export const createRecurringIssueSchema = z
  .object({
    orgId: orgIdSchema,
    projectId: projectIdSchema,
    title: z.string().min(3, "give the rule a title").max(180),
    priority: issuePrioritySchema.default("none"),
    assigneeId: userIdSchema.nullable().default(null),
    cadence: z.enum(["daily", "weekly"]),
    weekday: z.number().int().min(1).max(7).nullable().default(null),
    timezone: z.string().refine(isKnownTimeZone, "unknown time zone"),
    startsOn: z
      .string()
      .refine(isCalendarDate, "must be a real YYYY-MM-DD date"),
  })
  .superRefine((value, ctx) => {
    if (value.cadence === "weekly" && value.weekday === null) {
      ctx.addIssue({
        code: "custom",
        path: ["weekday"],
        message: "weekly rules need a weekday",
      });
    }
    if (value.cadence === "daily" && value.weekday !== null) {
      ctx.addIssue({
        code: "custom",
        path: ["weekday"],
        message: "daily rules take no weekday",
      });
    }
  });

export type CreateRecurringIssueInput = z.input<
  typeof createRecurringIssueSchema
>;
EOF
