import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringRepo from "@/server/repositories/recurring-issue-repository";
import { createIssue } from "@/server/services/issue-service";
import { projectResource } from "@/server/services/_support";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

const logger = createLogger("recurring-issue-job");

const DAY_MS = 86_400_000;

/** The calendar date (`YYYY-MM-DD`) it currently is in `timezone`. */
function localDate(now: Date, timezone: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: timezone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(now);
  const part = (type: string): string =>
    parts.find((entry) => entry.type === type)?.value ?? "";
  return `${part("year").padStart(4, "0")}-${part("month")}-${part("day")}`;
}

function dateToUtcMs(date: string): number {
  const [year, month, day] = date.split("-").map(Number) as [
    number,
    number,
    number,
  ];
  const value = new Date(0);
  value.setUTCFullYear(year, month - 1, day);
  return value.getTime();
}

/** ISO weekday: 1 = Monday … 7 = Sunday. */
function isoWeekday(date: string): number {
  const day = new Date(dateToUtcMs(date)).getUTCDay();
  return day === 0 ? 7 : day;
}

function shiftDays(date: string, days: number): string {
  return new Date(dateToUtcMs(date) + days * DAY_MS)
    .toISOString()
    .slice(0, 10);
}

/**
 * The latest occurrence that has started by `now`, or `null` if there is none.
 * Occurrence day D has started once the rule's local date has reached D.
 */
function latestOccurrence(rule: RecurringIssue, now: Date): string | null {
  const today = localDate(now, rule.timezone);

  let latest = today;
  if (rule.cadence === "weekly") {
    if (rule.weekday === null) return null;
    latest = shiftDays(today, -((isoWeekday(today) - rule.weekday + 7) % 7));
  }

  return latest >= rule.startsOn ? latest : null;
}

type Outcome = "created" | "unchanged";

async function processRule(rule: RecurringIssue, now: Date): Promise<Outcome> {
  const occurrence = latestOccurrence(rule, now);
  if (occurrence === null) return "unchanged";
  if (rule.lastOccurrenceOn !== null && occurrence <= rule.lastOccurrenceOn) {
    return "unchanged";
  }

  const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
  if (project === null) {
    throw new Error(`Project ${rule.projectId} was not found`);
  }
  if (isArchived(project)) return "unchanged";

  const creator = await memberRepo.findMember(rule.orgId, rule.createdBy);
  const actor: Actor | null =
    creator !== null && creator.status === "active"
      ? { userId: creator.userId, orgId: rule.orgId, role: creator.role }
      : null;

  if (actor === null || !can(actor, "issue:create", projectResource(project))) {
    await recurringRepo.setRecurringIssuePaused(rule.orgId, rule.id, true);
    return "unchanged";
  }

  let assigneeId = null;
  if (rule.assigneeId !== null) {
    const assignee = await memberRepo.findMember(rule.orgId, rule.assigneeId);
    if (assignee !== null && assignee.status === "active") {
      assigneeId = rule.assigneeId;
    }
  }

  await createIssue(actor, {
    orgId: rule.orgId,
    projectId: rule.projectId,
    title: `${rule.title} (${occurrence})`,
    description: null,
    status: "backlog",
    priority: rule.priority,
    assigneeId,
    parentId: null,
    estimate: null,
    dueAt: null,
    labelIds: [],
  });

  await recurringRepo.setLastOccurrenceOn(rule.orgId, rule.id, occurrence);
  return "created";
}

/**
 * Files at most one issue per rule — always for the latest started occurrence;
 * missed occurrences are never back-filled. A rule that fails is logged and
 * left as it was so a later run tries again, and never stops the others.
 */
export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringRepo.listActiveRecurringIssues();

    for (const rule of rules) {
      try {
        if ((await processRule(rule, now)) === "created") {
          result.processed += 1;
        }
      } catch (error) {
        result.failed += 1;
        logger.error("failed to file recurring issue", {
          recurringIssueId: rule.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}
EOF
