import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);
import { createRecurringIssueSchema } from "@/schemas/recurring-issue";
import { runRecurringIssueJob } from "@/server/jobs/recurring-issue-job";
import { drain, enqueue } from "@/server/jobs";
import * as svc from "@/server/services/recurring-issue-service";
import * as issueRepo from "@/server/repositories/issue-repository";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";

let cleanup: () => void;
let t: Tenant;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); t = await createTenant("rec", "starter"); });
afterAll(() => cleanup());

const base = (t: Tenant) => ({ orgId: t.org.id, projectId: t.project.id, title: "Daily triage", cadence: "daily" as const, timezone: "Asia/Tokyo", startsOn: "2026-03-01" });

describe("recurring", () => {
  it("schema", () => {
    const b = base(t);
    expect(createRecurringIssueSchema.safeParse({ ...b, orgId: "01HZZZAAAAAAAAAAAAAAAAAAAA", projectId: "01HZZZAAAAAAAAAAAAAAAAAAA1" }).success).toBe(true);
    const ok = { ...b, orgId: "01HZZZAAAAAAAAAAAAAAAAAAAA", projectId: "01HZZZAAAAAAAAAAAAAAAAAAA1" };
    expect(createRecurringIssueSchema.safeParse({ ...ok, startsOn: "2026-02-30" }).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse({ ...ok, timezone: "Mars/Base" }).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse({ ...ok, timezone: "+01:00" }).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse({ ...ok, cadence: "weekly" }).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse({ ...ok, weekday: 3 }).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse({ ...ok, cadence: "weekly", weekday: 3 }).success).toBe(true);
  });
  it("flow", async () => {
    const r = await svc.createRecurringIssue(t.actors.member, base(t));
    expect(r.paused).toBe(false);
    await svc.createRecurringIssue(t.actors.member, { ...base(t), cadence: "weekly", weekday: 4, title: "Weekly plan" });
    await svc.createRecurringIssue(t.actors.member, { ...base(t), title: "Third" });
    await expect(svc.createRecurringIssue(t.actors.member, { ...base(t), title: "Fourth" })).rejects.toThrow();
    await expect(svc.createRecurringIssue(t.actors.viewer, base(t))).rejects.toThrow();
    expect((await svc.listRecurringIssues(t.actors.viewer, t.org.id)).map((x) => x.title)).toEqual(["Daily triage", "Weekly plan", "Third"]);
    // 2026-03-04 15:30Z = 2026-03-05 00:30 JST (Thursday)
    const now = new Date("2026-03-04T15:30:00Z");
    const res = await runRecurringIssueJob(now);
    expect(res.processed).toBe(3);
    const list = await issueRepo.listIssues({ orgId: t.org.id, limit: 50 } as never);
    console.log(list.items.map((i) => i.title));
    expect((await runRecurringIssueJob(now)).processed).toBe(0);
    const later = new Date("2026-03-11T00:00:00Z"); // Wed 09:00 JST
    expect((await runRecurringIssueJob(later)).processed).toBe(3);
    const l2 = await issueRepo.listIssues({ orgId: t.org.id, limit: 50 } as never);
    console.log(l2.items.map((i) => i.title));
    await svc.setRecurringIssuePaused(t.actors.member, { orgId: t.org.id, recurringIssueId: r.id, paused: true });
    enqueue({ id: "x", kind: "recurring-issues", runAt: new Date(0).toISOString() as never, attempts: 0, payload: {} });
    expect(await drain()).toBe(1);
  });
});
EOF
