    const l2 = await issueRepo.listIssues({ orgId: t.org.id, limit: 50 } as never);
    console.log(l2.items.map((i) => i.title));
    await svc.setRecurringIssuePaused(t.actors.member, { orgId: t.org.id, recurringIssueId: r.id, paused: true });
    enqueue({ id: "x", kind: "recurring-issues", runAt: new Date(0).toISOString() as never, attempts: 0, payload: {} });
    expect(await drain()).toBe(1);
